import{_ as o,l,o as t,c as i,v as e,p as s,x as n,d as p,i as u,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Bouchaud 传播核","description":"","frontmatter":{"title":"Bouchaud 传播核","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bouchaud-propagator.md","filePath":"quant/bouchaud-propagator.md","lastUpdated":1789023840000}'),d={name:"quant/bouchaud-propagator.md"};function c(m,a,G,E,B,_){const r=l("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="bouchaud-传播核" tabindex="-1">Bouchaud 传播核 <a class="header-anchor" href="#bouchaud-传播核" aria-label="Permalink to &quot;Bouchaud 传播核&quot;">​</a></h1><div class="epigraph"><p>单笔带符号成交对未来价格的平均影响不是一个永久台阶，而是随时间衰减的核：把这些核叠在一条相关的订单流上，才能同时看到凹的冲击与缓慢的价格扩散。</p><footer>—— Bouchaud, Gefen, Potters and Wyart, Fluctuations and response in financial markets: the subtle nature of &#39;random&#39; price changes, Quantitative Finance, 2004</footer></div><p><a href="/quant/temp-perm-impact">瞬时冲击与永久冲击</a> 把一次母单的短fall 切成可恢复与留下的两块，并引用 Gatheral 对核形状的无动态套利约束。Bouchaud 等人的传播函数（propagator）把同一思想写成事件层面的线性响应：中点（或成交价）相对历史带符号成交的平均反应是 \\(G(\\tau)\\)，而不是两个数字。订单流本身高度自相关——切片让同号成交成串——若每笔留下永久台阶，价格波动会爆掉；经验上 \\(G(\\tau)\\) 衰减，正好对冲订单流的记忆，使价格接近扩散。本篇写 \\(G\\) 的估计、与平方根母单冲击的叠加关系，以及它和 <a href="/quant/ofi-cont">OFI</a> 短窗线性冲击的尺度差异。它解释平均响应，不提供操纵价格的配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记第 \\(n\\) 笔成交的符号 \\(\\epsilon_n=\\pm 1\\)（主动买为正），价格为 \\(p_n\\)。最简单的传播模型是</p> \\[p_n=p_{-\\infty}+\\sum_{n&#39;\\lt n}G(n-n&#39;)\\,\\epsilon_{n&#39;}+\\eta_n, \\]<p>其中 \\(G\\) 是离散事件时间上的核，\\(\\eta\\) 是与过去 \\(\\epsilon\\) 正交的新息。若 \\(G\\) 为常数（永久线性冲击），而 \\(\\epsilon\\) 又像长记忆过程那样正相关，则 \\(p\\) 的方差超线性增长，与近似扩散的价格矛盾。Bouchaud–Gefen–Potters–Wyart 指出：必须让 \\(G(\\tau)\\) 衰减，衰减的速度与订单流的相关结构匹配，价格才能既对每一笔有响应、又不爆炸。问题是估计 \\(G\\)、判断它衰减到零还是到一个平台（真正的永久部分），以及母单尺度的平方根如何从单笔核里冒出来。</p><p>第二个问题是时钟。\\(G\\) 可以定义在成交笔数、成交量时间或墙钟上。笔数时钟在活跃时走得快；墙钟便于和执行的「三十分钟」对齐。混用会让半衰期不可比。</p><h3 id="从相关订单流到必须衰减的核" tabindex="-1">从相关订单流到必须衰减的核 <a class="header-anchor" href="#从相关订单流到必须衰减的核" aria-label="Permalink to &quot;从相关订单流到必须衰减的核&quot;">​</a></h3><p>设 \\(\\epsilon\\) 的相关 \\(C(\\ell)=\\mathbb{E}[\\epsilon_n\\epsilon_{n+\\ell}]\\) 缓慢下降。价格增量的二阶结构要求 \\(G\\) 与 \\(C\\) 之间近似满足一组卷积方程：响应在低频处不能把订单流的能量原样放大。直观上，\\(G\\) 常被拟成幂律 \\(G(\\tau)\\propto\\tau^{-\\gamma}\\)，\\(\\gamma\\) 约在 \\(0.25\\) 附近的文献值只是某一市场某一时钟上的经验，不是常数定律。估计应同时报告 \\(C(\\ell)\\)：核的衰减若来自你把相关符号当成独立冲击，识别是错的。</p><p><span class="marginnote">传播核是平均线性响应，对大单非线性、对状态依赖冲击都只是一阶。薄档上的打穿不是 \\(G\\) 能描述的几何，那是簿的阶梯。\\(G\\) 更适合「许多普通主动单」的平均余波。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>事件研究。</strong> 对每笔主动成交，看随后 \\(\\tau\\) 步的中点变化乘上 \\(\\epsilon_n\\)，再平均。得到的是含后续成交的<strong>总响应</strong>，不是干净的 \\(G\\)，因为后续 \\(\\epsilon\\) 还在贡献。要识别 \\(G\\)，需要从总响应里解出与 \\(C\\) 的耦合，或用工具变量式的回归：把 \\(p\\) 对滞后的 \\(\\epsilon\\) 做分布滞后，控制更近的成交。实务上常用 Bouchaud 等人给出的近似反演，或直接在回归里加足够多的滞后。</p><p><strong>与 OFI。</strong> CKS 的 \\(\\Delta m=\\beta\\,\\mathrm{OFI}\\) 是极短窗、把增撤成一并会计后的斜率，接近 \\(G(0^+)\\) 附近的瞬时响应，但自变量不是纯成交符号。传播核传统上用成交；也可以对 OFI 增量定义一个核，描述簿事件的余波。不要把 \\(\\beta\\) 和一个衰减 10 分钟的 \\(G(10\\mathrm{min})\\) 比大小而不声明窗口。</p><p><strong>母单。</strong> 把同向连续子单标成母单后，母单冲击是子单传播的叠加。若子单在事件时间上近似均匀注入，叠加后的峰值冲击可以对母单量呈凹形，接近平方根——这是通往 Tóth 定律的微观桥，细节在 <a href="/quant/square-root-impact-law">平方根冲击律</a>。估计母单 \\(G\\) 时必须处理重叠：两个母单的核在日历上纠缠，应用稀疏的母单样本或显式叠加模型。</p><h3 id="gatheral-约束在-上的含义" tabindex="-1">Gatheral 约束在 \\(G\\) 上的含义 <a class="header-anchor" href="#gatheral-约束在-上的含义" aria-label="Permalink to &quot;Gatheral 约束在 $G$ 上的含义&quot;">​</a></h3><p>无动态套利要求：不能通过一来一回的确定性交易从核里锁利润。这限制了 \\(G\\) 的凸性/正定性类性质，排除「先制造冲击再完全反向恢复且留下利润」的某些形状。经验幂律衰减若过慢或过快，都可能在模型里出现准套利；与 Huberman–Stanzl 的「永久部分必须线性」合在一起：把 \\(G(\\infty)\\) 设成与单笔量无关的平台可以，把 \\(G(\\infty)\\propto\\sqrt{q}\\) 当永久则冲突。识别上应允许 \\(G(\\tau)=G_{\\mathrm{temp}}(\\tau)+G_\\infty\\)，并对 \\(G_\\infty\\) 做线性设定，把凹性留给暂时项。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机械层：一笔主动买吃掉卖档，中点上跳；随后限价补货、反向主动卖、做市存货调整，使中点部分回落。\\(G(\\tau)\\) 的下降段就是恢复力的平均时间结构，与 Hawkes 里 \\(M^b\\to L^a\\) 的核是同一回路的不同投影——一个看价格，一个看事件。信息层：若成交携带关于价值的信息，应留下 \\(G_\\infty\\gt 0\\)。经验上两者缠在一起：即使完全非知情的切片，只要订单流可预测，做市商的条件期望也会移动，看起来像永久；随后若发现只是切片，价格再退回。Lillo、Farmer 与 Bouchaud 对订单流记忆的讨论，正是在说「可预测的流不应产生可预测的价格」，于是冲击必须随时间调整。</p><p>因此传播核是市场对<strong>可预测订单流</strong>的折扣装置。把 \\(G\\) 当成外生成本去优化执行，而不把你自己的流的可预测性考虑进去，会高估或低估真实短fall：你的切片越规律，市场越能把暂时冲击从你身上抽走。这与最优执行里「隐藏节奏」的直觉一致，但不构成本篇的操作建议——只说明 \\(G\\) 对策略类不是不变的。</p><h3 id="线性核的叠加如何长出凹冲击" tabindex="-1">线性核的叠加如何长出凹冲击 <a class="header-anchor" href="#线性核的叠加如何长出凹冲击" aria-label="Permalink to &quot;线性核的叠加如何长出凹冲击&quot;">​</a></h3><p>单笔响应若对符号线性、对量也近似线性（小单），母单量 \\(Q=nq\\) 的峰值影响并不是 \\(nG\\)，因为后续子单发生在前面子单的 \\(G\\) 已经开始衰减之时，且子单符号完全相关。叠加积分给出对 \\(n\\) 凹的函数。选择合适的 \\(G\\) 衰减与注入速度，凹性可以接近平方根。关键句：平方根不必在单笔上成立，它可以是传播过程的宏观外观。反过来，在单笔上拟合 \\(\\sqrt{q}\\) 再加总，会双重计算凹性。校准应选一层：要么事件核，要么母单定律，再交叉验证另一层。</p><p><span class="marginnote">\\(\\eta_n\\) 里包含新闻与他市场冲击。把所有中点变动都归因于本地 \\(\\epsilon\\)，会让 \\(G\\) 在宏观日被抬高。应做市场调整，或把指数期货的符号当作额外的传播项。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(G\\) 在制度切换时不平稳：开盘、拍卖、涨跌停、流动性撤离。全样本一条核会把不同体制平均成一条谁都不能用的曲线。事件分类错误直接翻转 \\(\\epsilon\\)，核被向零拉。隐藏成交让可见符号序列不完整。碎片化市场里本地 \\(G\\) 解释不了 NBBO。</p><p>不要在 Almgren–Chriss 的闭式轨迹里把瞬时项换成任意 \\(G\\) 还沿用原解。不要用五分钟 bar 的回归斜率叫做传播核。不要从 \\(G\\) 的幂律指数直接推出容量。A 股午休切断卷积；隔夜更不是同一个 \\(G\\)。</p><p><span class="marginnote">传播模型是描述性的线性响应。它不能证明某笔成交「没有信息」或「全是信息」，只能给出平均衰减。个例路径可以完全不像平均核。</span></p>',27)),(t(),s(h,null,{default:n(()=>[u(r,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20Eps%5B%22%E5%B8%A6%E7%AC%A6%E5%8F%B7%E6%88%90%E4%BA%A4%20%CE%B5%22%5D%20--%3E%20G%5B%22%E6%A0%B8%20G(%CF%84)%22%5D%0A%20%20Eps%20--%3E%20C%5B%22%E8%AE%A2%E5%8D%95%E6%B5%81%E7%9B%B8%E5%85%B3%20C(%E2%84%93)%22%5D%0A%20%20G%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%E8%B7%AF%E5%BE%84%22%5D%0A%20%20C%20--%3E%20P%0A%20%20G%20--%3E%20Super%5B%22%E5%90%8C%E5%90%91%E5%AD%90%E5%8D%95%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20Super%20--%3E%20Sqrt%5B%22%E6%AF%8D%E5%8D%95%E5%B0%BA%E5%BA%A6%E7%9A%84%E5%87%B9%E5%86%B2%E5%87%BB%22%5D%0A%20%20News%5B%22%E5%A4%96%E7%94%9F%E6%96%B0%E6%81%AF%20%CE%B7%22%5D%20--%3E%20P%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bouchaud 传播核 \\(G(\\tau)\\) 是带符号成交对价格的平均线性响应；衰减用来对冲订单流记忆，使价格仍接近扩散。</li><li>估计必须处理后续成交的叠加，不能把原始事件研究曲线直接叫做 \\(G\\)。</li><li>永久部分受 Huberman–Stanzl 与 Gatheral 约束；凹性应主要留在暂时项。</li><li>母单平方根可以由单笔核的叠加长出，不必要求每一笔都服从根号。</li><li>体制、分类、碎片化与自身订单流的可预测性，使 \\(G\\) 不能当不变成本表。</li><li>出处：Bouchaud, Gefen, Potters and Wyart, <em>Quantitative Finance</em>, 2004；后续综述见 Bouchaud, Farmer, Lillo 等对订单流记忆与价格冲击的工作。</li></ul>',2))])}const b=o(d,[["render",c]]);export{A as __pageData,b as default};
